"use client";

import { motion } from "framer-motion";
import { ArrowRight, Clock, Calendar, User } from "lucide-react";
interface FeaturedArticleProps {
  onSelectPost?: (postId: string) => void;
  posts?: any[];
}

export default function FeaturedArticle({ onSelectPost, posts = [] }: FeaturedArticleProps) {
  // Grab the featured post, fallback to the first post
  const post = posts.find((p) => p.featured) || posts[0];
  const isVideo =
  /\.(mp4|webm|ogg|mov|m4v|avi|mkv)$/i.test(post.thumbnail);

  if (!post) return null;

  return (
    <section id="featured-story" className="relative py-24 bg-background border-y border-white/5 overflow-hidden">
      {/* Background ambient lighting */}
      <div className="absolute inset-0 pointer-events-none z-0">
        <div className="absolute top-[20%] right-[10%] w-[450px] h-[350px] bg-accent-green/5 rounded-full blur-[130px] opacity-75" />
        <div className="absolute bottom-[10%] left-[5%] w-[400px] h-[300px] bg-purple-900/5 rounded-full blur-[140px] opacity-60" />
      </div>

      <div className="max-w-[1400px] mx-auto px-6 md:px-12 relative z-10">
        
        {/* Section Title */}
        <motion.div
          initial={{ opacity: 0, x: -20 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.6 }}
          className="flex items-center gap-4 mb-10"
        >
          <span className="h-[2px] w-8 bg-accent-green" />
          <h2 className="text-xs font-sans font-bold tracking-[0.3em] uppercase text-accent-green">
            Featured Masterpiece
          </h2>
        </motion.div>

        {/* Massive Featured Grid Card */}
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.8 }}
          className="group relative grid lg:grid-cols-12 gap-0 rounded-3xl overflow-hidden border border-white/10 bg-secondary-dark/40 shadow-[0_30px_70px_rgba(0,0,0,0.85)] backdrop-blur-xl"
        >
          {/* Glowing border outline on hover */}
          <div className="absolute inset-0 border border-accent-green/0 group-hover:border-accent-green/20 rounded-3xl pointer-events-none transition-colors duration-500 z-30" />

          {/* Left / Upper: Cinematic Thumbnail (7 Columns) */}
         {/* Left / Upper: Instagram Style Thumbnail */}
<div className="lg:col-span-5 flex items-center justify-center bg-black/30 p-8">

  <div className="relative w-full max-w-[480px] aspect-[4/5] overflow-hidden rounded-3xl border border-white/10 shadow-2xl">

    {/* Overlay */}
    <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent z-10 pointer-events-none" />

    {isVideo ? (
      <video
        src={post.thumbnail}
        muted
        loop
        playsInline
        autoPlay
        controls={false}
        className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
      />
    ) : (
      <img
        src={post.thumbnail}
        alt={post.title}
        className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
      />
    )}

    {/* Badges */}
    <div className="absolute top-5 left-5 z-20 flex gap-2">
      <span className="bg-accent-green text-black font-extrabold text-[9px] uppercase tracking-widest px-3 py-1.5 rounded-full">
        {post.category}
      </span>

      <span className="glass text-white font-bold text-[9px] uppercase tracking-widest px-3 py-1.5 rounded-full flex items-center gap-1">
        <Clock size={10} className="text-accent-green" />
        {post.readingTime}
      </span>
    </div>

  </div>

</div>

          {/* Right / Lower: Content & Meta (5 Columns) */}
          <div className="lg:col-span-7 flex flex-col justify-between p-8 sm:p-12 relative z-20">
            {/* Soft inner ambient glow */}
            <div className="absolute top-0 right-0 w-[200px] h-[200px] bg-accent-green/2 rounded-full blur-[60px] pointer-events-none" />

            <div className="flex flex-col gap-6">
              {/* Publication Date */}
              <div className="flex items-center gap-2 text-white/40 text-[10px] font-sans font-bold uppercase tracking-widest">
                <Calendar size={12} className="text-accent-green" />
                <span>{post.date}</span>
              </div>

              {/* Title */}
              <h3 className="text-3xl sm:text-4xl lg:text-[2.2rem] font-heading font-black text-white uppercase tracking-wide leading-[1.05] group-hover:text-accent-green transition-colors duration-300">
                {post.title}
              </h3>

              {/* Excerpt */}
              <p className="text-sm text-muted-text font-sans leading-relaxed tracking-wide">
                {post.excerpt}
              </p>
            </div>

            {/* Author and Action Tray */}
            <div className="mt-12 pt-8 border-t border-white/5 flex flex-col sm:flex-row sm:items-center justify-between gap-6">
              
              {/* Author badge */}
              <div className="flex items-center gap-3.5">
                <img
                  src={post.author.avatar}
                  alt={post.author.name}
                  className="h-10 w-10 rounded-full border border-white/10 object-cover"
                />
                <div className="flex flex-col">
                  <span className="text-xs font-bold text-white uppercase tracking-wider">
                    {post.author.name}
                  </span>
                  <span className="text-[10px] text-muted-text uppercase tracking-widest mt-0.5">
                    {post.author.role}
                  </span>
                </div>
              </div>

              {/* Action Button */}
              <button 
                onClick={() => onSelectPost?.(post.slug)}
                className="group/btn px-6 py-3.5 rounded-full border border-white/10 text-white font-bold text-xs uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-accent-green hover:text-black hover:border-accent-green hover:shadow-[0_0_20px_rgba(0,217,95,0.25)] transition-all duration-300 shrink-0"
              >
                Read Article
                <ArrowRight size={14} className="group-hover/btn:translate-x-1 transition-transform" />
              </button>

            </div>

          </div>

        </motion.div>

      </div>
    </section>
  );
}
