"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Send, CheckCircle2, Shield } from "lucide-react";

export default function BlogNewsletter() {
  const [email, setEmail] = useState("");
  const [isSubmitted, setIsSubmitted] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!email) return;

    try {
      await fetch("https://formsubmit.co/ajax/info@houseofwasila.com", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
        },
        body: JSON.stringify({
          email: email,
          _subject: "New Newsletter Subscriber",
        }),
      });

      setIsSubmitted(true);
      setEmail("");
    } catch (error) {
      console.log(error);
    }
  };

  return (
    <section className="relative py-24 bg-background overflow-hidden border-t border-white/5">
      {/* Background spotlights */}
      <div className="absolute inset-0 pointer-events-none z-0">
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[350px] bg-accent-green/4 rounded-full blur-[160px]" />
      </div>

      <div className="max-w-[1200px] mx-auto px-6 relative z-10">

        {/* Massive Glassmorphic Capsule */}
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.8 }}
          className="relative rounded-[32px] border border-white/10 bg-secondary-dark/30 backdrop-blur-xl p-8 sm:p-16 overflow-hidden shadow-[0_30px_70px_rgba(0,0,0,0.8)]"
        >
          {/* Inner radial line patterns */}
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(255,255,255,0.01)_1px,transparent_1px)] bg-[size:24px_24px] opacity-60 pointer-events-none" />

          {/* Glowing accent dot */}
          <div className="absolute top-0 right-0 w-[200px] h-[200px] bg-accent-green/5 rounded-full blur-[60px] pointer-events-none" />

          <div className="grid lg:grid-cols-12 gap-10 lg:gap-16 items-center relative z-10">

            {/* LEFT SIDE */}
            <div className="lg:col-span-7 flex flex-col gap-6 text-left">

              <div className="flex items-center gap-3">
                <span className="flex h-1.5 w-1.5 rounded-full bg-accent-green animate-pulse" />
                <span className="text-[10px] font-sans font-bold tracking-[0.3em] uppercase text-accent-green">
                  Weekly Dispatch Ingest
                </span>
              </div>

              <h2 className="text-3xl sm:text-4xl lg:text-5xl font-heading font-black text-white uppercase tracking-wider leading-none">
                Subscribe To The <br />
                <span className="text-gradient">Wasila Intel Feed.</span>
              </h2>

              <p className="text-sm text-muted-text font-sans leading-relaxed tracking-wide max-w-lg">
                Stay updated with behind-the-scenes engineering breakdowns,
                creator growth models, live broadcasting schedules, and
                industry dispatches curated by our editorial team.
              </p>

              <div className="flex items-center gap-2 text-white/30 text-[9px] font-sans font-bold tracking-widest uppercase mt-2">
                <Shield size={12} className="text-accent-green" />
                <span>Zero Spam • Instant Unsubscribe • Verified TLS Sync</span>
              </div>

            </div>

            {/* RIGHT SIDE */}
            <div className="lg:col-span-5 w-full">

              <AnimatePresence mode="wait">

                {!isSubmitted ? (

                  <motion.form
                    onSubmit={handleSubmit}
                    key="newsletter-form"
                    initial={{ opacity: 0, x: 20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: -20 }}
                    transition={{ duration: 0.4 }}
                    className="flex flex-col gap-4"
                  >

                    {/* EMAIL INPUT */}
                    <div className="relative">

                      <div className="absolute inset-0 bg-accent-green/5 rounded-2xl blur-sm opacity-0 focus-within:opacity-100 transition-opacity duration-300 pointer-events-none" />

                      <input
                        type="email"
                        required
                        placeholder="Enter your corporate email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        className="w-full bg-black/60 hover:bg-black/80 focus:bg-black border border-white/10 focus:border-accent-green/40 rounded-2xl px-6 py-4 text-sm font-sans tracking-wide text-white placeholder-white/35 focus:outline-none transition-all duration-300 focus:shadow-[0_0_20px_rgba(0,217,95,0.05)]"
                      />

                    </div>

                    {/* SUBMIT BUTTON */}
                    <button
                      type="submit"
                      className="group relative flex items-center justify-center gap-3 w-full py-4 rounded-2xl bg-accent-green text-black font-extrabold text-xs uppercase tracking-[0.25em] shadow-[0_0_25px_rgba(0,217,95,0.2)] hover:shadow-[0_0_35px_rgba(0,217,95,0.45)] hover:bg-white transition-all duration-300 cursor-pointer"
                    >
                      Join Broadcast List

                      <Send
                        size={12}
                        className="group-hover:translate-x-1 group-hover:-translate-y-0.5 transition-transform duration-300"
                      />
                    </button>

                  </motion.form>

                ) : (

                  <motion.div
                    key="newsletter-success"
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0 }}
                    transition={{
                      type: "spring",
                      stiffness: 300,
                      damping: 25
                    }}
                    className="flex flex-col items-center justify-center text-center p-8 rounded-2xl bg-black/40 border border-accent-green/20 relative overflow-hidden"
                  >

                    {/* Glow */}
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-48 h-48 bg-accent-green/10 rounded-full blur-[40px] pointer-events-none" />

                    <CheckCircle2
                      size={44}
                      className="text-accent-green mb-4 drop-shadow-[0_0_10px_#00db5f]"
                    />

                    <h3 className="text-lg font-heading text-white uppercase tracking-widest mb-2">
                      Ingestion Verified
                    </h3>

                    <p className="text-xs text-muted-text font-sans leading-relaxed max-w-xs">
                      Your connection key has been synced successfully.
                      Welcome to the House of Wasila editorial feed.
                    </p>

                  </motion.div>

                )}

              </AnimatePresence>

            </div>

          </div>

        </motion.div>

      </div>
    </section>
  );
}