"use client";

import { useState, useEffect } from "react";
import BlogHero from "@/sections/blog/Hero";
import FeaturedArticle from "@/sections/blog/FeaturedArticle";
import TrendingArticles from "@/sections/blog/TrendingArticles";
import LatestGrid from "@/sections/blog/LatestGrid";
import BlogNewsletter from "@/sections/blog/Newsletter";
import BlogCTA from "@/sections/blog/PremiumCTA";
import { useRouter } from "next/navigation";
import { FolderOpen } from "lucide-react";
import { getApiUrl, resolveImageUrl } from "@/utils/api";

export default function BlogPageClient() {
  const [posts, setPosts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const router = useRouter();

  useEffect(() => {
    async function fetchBlogs() {
      try {
        const apiUrl = getApiUrl();
        const res = await fetch(`${apiUrl}/api/blogs?status=Published&limit=100`);
        if (!res.ok) throw new Error("Failed to fetch");
        const json = await res.json();
        
        // Map backend data to frontend format
        const mappedPosts = json.data.map((post: any, index: number) => {
          // Simple reading time calculation
          const wordCount = post.excerpt ? post.excerpt.split(" ").length : 0;
          const readingTime = Math.max(1, Math.ceil(wordCount / 200) + 3) + " min read";
          console.log(post.featuredImage);
console.log(resolveImageUrl(post.featuredImage));
          
          return {
            id: post._id,
            slug: post.slug,
            title: post.title,
            excerpt: post.excerpt,
            content: post.content,
            category: post.category,
            author: {
              name: post.author || "Admin",
              role: "Author",
              avatar: "https://ui-avatars.com/api/?name=" + encodeURIComponent(post.author || "Admin") + "&background=random"
            },
            date: new Date(post.createdAt).toLocaleDateString("en-US", { month: "short", day: "2-digit", year: "numeric" }),
            readingTime,
            thumbnail: resolveImageUrl(post.featuredImage),
            
            featured: index === 0, // Make first post featured
            trending: index > 0 && index <= 3 // Make next 3 trending
          };
        });
        
        setPosts(mappedPosts);
      } catch (err) {
        console.error(err);
        setError(true);
      } finally {
        setLoading(false);
      }
    }
    fetchBlogs();
  }, []);

  const handleSelectPost = (slug: string) => {
    router.push(`/blog/${slug}`);
  };

  if (loading) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center bg-background">
        <div className="w-12 h-12 border-4 border-white/10 border-t-accent-green rounded-full animate-spin"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-[60vh] flex flex-col items-center justify-center bg-background text-white">
        <h2 className="text-2xl font-heading mb-2">Error Loading Blog</h2>
        <p className="text-muted-text">Please try again later.</p>
      </div>
    );
  }

  if (posts.length === 0) {
    return (
      <div className="min-h-[60vh] flex flex-col items-center justify-center bg-background text-white">
        <div className="h-16 w-16 rounded-full bg-white/[0.02] border border-white/10 flex items-center justify-center text-white/20 mb-6">
          <FolderOpen size={32} />
        </div>
        <h2 className="text-2xl font-heading mb-2">No Stories Available</h2>
        <p className="text-muted-text">Check back soon for new content.</p>
      </div>
    );
  }

  return (
    <>
      <BlogHero posts={posts} />
      <FeaturedArticle posts={posts} onSelectPost={handleSelectPost} />
      <TrendingArticles posts={posts} onSelectPost={handleSelectPost} />
      <LatestGrid posts={posts} onSelectPost={handleSelectPost}  />
      <BlogNewsletter />
      <BlogCTA />
    </>
  );
}
