"use client";

import { motion } from "framer-motion";
import { Clock, TrendingUp, Play } from "lucide-react";
// import { blogPosts } from "@/data/blog";
interface TrendingArticlesProps {
  onSelectPost?: (postId: string) => void;
  posts?: any[];
}

export default function TrendingArticles({ onSelectPost, posts = [] }: TrendingArticlesProps) {
  // Filter trending posts
  const trendingPosts = posts.filter((p) => p.trending);

  const containerVariants = {
    hidden: {},
    visible: {
      transition: {
        staggerChildren: 0.15
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.5,
        ease: [0.25, 0.1, 0.25, 1] as [number, number, number, number],
      },
    },
  };

  return (
    <section className="relative py-20 bg-background overflow-hidden">
      {/* Subtle background ambient light */}
      <div className="absolute inset-0 pointer-events-none z-0">
        <div className="absolute top-[50%] left-[50%] -translate-x-1/2 w-[700px] h-[300px] bg-accent-green/3 rounded-full blur-[150px]" />
      </div>

      <div className="max-w-[1400px] mx-auto px-6 md:px-12 relative z-10">

        {/* Section Heading */}
        <div className="flex items-center justify-between mb-12">
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6 }}
            className="flex items-center gap-4"
          >
            <span className="h-[2px] w-8 bg-accent-green" />
            <h2 className="text-xs font-sans font-bold tracking-[0.3em] uppercase text-accent-green flex items-center gap-2">
              Trending Stories <TrendingUp size={14} className="animate-pulse" />
            </h2>
          </motion.div>
          <div className="h-[1px] flex-grow bg-white/5 ml-6 hidden md:block" />
        </div>

        {/* Trending Horizontal Cards Grid */}
        <motion.div
          variants={containerVariants}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-100px" }}
          className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 lg:gap-8"
        >
          {trendingPosts.map((post, idx) => {
  const isVideo =
    /\.(mp4|webm|ogg|mov|m4v|avi|mkv)$/i.test(post.thumbnail);

  return (
            <motion.div
              key={post.id}
              variants={itemVariants}
              onClick={() => onSelectPost?.(post.slug)}
              className="group flex gap-5 items-center p-5 rounded-2xl bg-secondary-dark/20 border border-white/5 hover:border-accent-green/20 hover:bg-secondary-dark/60 transition-all duration-300 cursor-pointer shadow-lg relative overflow-hidden"
            >
              {/* Inner subtle glow overlay */}
              <div className="absolute inset-0 bg-gradient-to-r from-accent-green/0 via-accent-green/[0.02] to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none" />

              {/* Number Index (Bebas Neue Outline Style) */}
              <span className="text-5xl sm:text-6xl font-heading font-black text-transparent [-webkit-text-stroke:1px_rgba(255,255,255,0.12)] group-hover:[-webkit-text-stroke:1px_rgba(0,217,95,0.4)] tracking-tight shrink-0 transition-colors duration-300 select-none">
                {String(idx + 1).padStart(2, "0")}
              </span>

              {/* Cinematic Thumbnail Socket */}
              <div className="w-[100px] h-[72px] sm:w-[120px] sm:h-[86px] rounded-xl overflow-hidden relative shrink-0 border border-white/5 shadow-md">

  {isVideo ? (
    <video
      src={post.thumbnail}
      muted
      loop
      autoPlay
      playsInline
      className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
    />
  ) : (
    <img
      src={post.thumbnail}
      alt={post.title}
      className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
    />
  )}

  <div className="absolute inset-0 bg-black/20 group-hover:bg-transparent transition-colors duration-300" />

  {isVideo && (
    <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
      <div className="w-8 h-8 rounded-full bg-black/60 backdrop-blur-md border border-white/20 flex items-center justify-center">
        <Play size={14} fill="white" className="text-white ml-0.5" />
      </div>
    </div>
  )}
</div>

              {/* Details column */}
              <div className="flex flex-col justify-between min-w-0 flex-grow gap-2">

                {/* Category & Time */}
                <div className="flex items-center gap-2 text-[9px] font-sans font-bold uppercase tracking-widest text-muted-text">
                  <span className="text-accent-green font-extrabold">{post.category}</span>
                  <span>•</span>
                  <span className="flex items-center gap-1">
                    <Clock size={10} className="text-white/30" />
                    {post.readingTime}
                  </span>
                </div>

                {/* Post Title */}
                <h3 className="text-sm font-sans font-bold text-white group-hover:text-accent-green transition-colors duration-300 leading-snug tracking-wide line-clamp-2">
                  {post.title}
                </h3>

                {/* Author Name */}
                <span className="text-[9px] font-sans font-medium text-white/40 group-hover:text-white/60 transition-colors duration-300 tracking-wider">
                  By {post.author.name}
                </span>

              </div>

            </motion.div>
  );
})}
        </motion.div>

      </div>
    </section>
  );
}
