"use client";

import React, { useState, useMemo, useEffect, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Search, Clock, Calendar, ArrowUpRight, FolderOpen, RefreshCw } from "lucide-react";
import { BlogCategory } from "@/data/blog";
import { ExpandableExcerpt } from "./ExpandableExcerpt";

interface LatestGridProps {
  onSelectPost?: (postId: string) => void;
  posts?: any[];
}

const CATEGORIES: ("All" | BlogCategory)[] = [
  "All",
  "Records",
  "Production",
  "Islamic",
  "Sports",
  "News",
  "Digital",
  "Kids",
];

export default function LatestGrid({ onSelectPost, posts = [] }: LatestGridProps) {
  const [selectedCategory, setSelectedCategory] = useState<"All" | BlogCategory>("All");
  const [searchQuery, setSearchQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const sectionRef = useRef<HTMLElement>(null);

  // Filter posts based on category and search query
  const filteredPosts = useMemo(() => {
    return posts.filter((post) => {
     
      const matchesCategory = selectedCategory === "All" || post.category === selectedCategory;
      const matchesSearch = 
        post.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        post.excerpt.toLowerCase().includes(searchQuery.toLowerCase()) ||
        post.author.name.toLowerCase().includes(searchQuery.toLowerCase());
        
      return matchesCategory && matchesSearch;
    });
    
  }, [selectedCategory, searchQuery]);

  // Reset page to 1 on filter or search change
  useEffect(() => {
    setCurrentPage(1);
  }, [selectedCategory, searchQuery]);

  const postsPerPage = 9;
  const totalPages = Math.ceil(filteredPosts.length / postsPerPage);

  const paginatedPosts = useMemo(() => {
    const startIndex = (currentPage - 1) * postsPerPage;
    return filteredPosts.slice(startIndex, startIndex + postsPerPage);
  }, [filteredPosts, currentPage]);

  const resetFilters = () => {
    setSelectedCategory("All");
    setSearchQuery("");
    setCurrentPage(1);
  };

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
    if (sectionRef.current) {
      sectionRef.current.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  
  return (
    <section id="all-stories" ref={sectionRef} className="relative py-20 bg-background overflow-hidden">
      {/* Background spotlights */}
      <div className="absolute inset-0 pointer-events-none z-0">
        <div className="absolute top-[20%] left-[-10%] w-[500px] h-[500px] bg-accent-green/2 rounded-full blur-[150px]" />
        <div className="absolute bottom-[20%] right-[-10%] w-[500px] h-[500px] bg-purple-900/3 rounded-full blur-[160px]" />
      </div>

      <div className="max-w-[1400px] mx-auto px-6 md:px-12 relative z-10">
        
        {/* Filter & Search Header Panel */}
        <div className="flex flex-col gap-8 mb-16 border-b border-white/5 pb-10">
          
          {/* Top Row: Section Title & Live Search Input */}
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
            
            <div className="flex items-center gap-4">
              <span className="h-[2px] w-8 bg-accent-green" />
              <h2 className="text-xs font-sans font-bold tracking-[0.3em] uppercase text-accent-green">
                Latest Dispatch Grid
              </h2>
            </div>

            {/* Glowing Search Box */}
            <div className="relative w-full lg:max-w-md">
              <div className="absolute inset-0 bg-accent-green/5 rounded-full blur-md opacity-0 focus-within:opacity-100 transition-opacity duration-300 pointer-events-none" />
              <div className="relative flex items-center">
                <Search size={16} className="absolute left-5 text-white/40" />
                <input
                  type="text"
                  placeholder="Search articles, creators, insights..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full bg-secondary-dark/60 hover:bg-secondary-dark/80 focus:bg-black/80 border border-white/10 focus:border-accent-green/40 px-12 py-3.5 rounded-full text-sm font-sans tracking-wide text-white placeholder-white/35 focus:outline-none transition-all duration-300 focus:shadow-[0_0_20px_rgba(0,217,95,0.08)]"
                />
                {searchQuery && (
                  <button 
                    onClick={() => setSearchQuery("")}
                    className="absolute right-5 text-xs text-white/40 hover:text-white/80 transition-colors"
                  >
                    Clear
                  </button>
                )}
              </div>
            </div>

          </div>

          {/* Bottom Row: Pill Filters (Scrollable on Mobile) */}
          <div className="w-full overflow-x-auto pb-4 -mb-4 scrollbar-none">
            <div className="flex gap-2.5 min-w-max pr-6">
              {CATEGORIES.map((category) => {
                const isActive = selectedCategory === category;
                
                return (
                  <button
                    key={category}
                    onClick={() => setSelectedCategory(category)}
                    className={`relative px-6 py-2.5 rounded-full text-[10px] font-sans font-bold uppercase tracking-widest transition-colors duration-300 ${
                      isActive ? "text-black" : "text-white/60 hover:text-white hover:bg-white/[0.03]"
                    }`}
                  >
                    {/* Active Pill Bubble background */}
                    {isActive && (
                      <motion.div
                        layoutId="activeCategoryBubble"
                        transition={{ type: "spring", stiffness: 380, damping: 30 }}
                        className="absolute inset-0 bg-accent-green rounded-full z-0 shadow-[0_0_20px_rgba(0,217,95,0.35)]"
                      />
                    )}
                    <span className="relative z-10">{category}</span>
                  </button>
                );
              })}
            </div>
          </div>

        </div>

        {/* Dynamic Shuffle Articles Grid */}
        <motion.div layout className="relative">
          <AnimatePresence mode="popLayout">
            {paginatedPosts.length > 0 ? (
              <motion.div 
                layout
                className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 lg:gap-10"
              >
                {paginatedPosts.map((post) => {
  const isVideo =
    /\.(mp4|webm|ogg|mov|m4v|avi|mkv)$/i.test(post.thumbnail);

  return (
    <motion.article
      key={post.id}
      layout
      initial={{ opacity: 0, scale: 0.96 }}
      animate={{ opacity: 1, scale: 1 }}
      exit={{ opacity: 0, scale: 0.96 }}
      transition={{ duration: 0.5 }}
      onClick={() => onSelectPost?.(post.slug)}
      className="group flex flex-col justify-between h-full bg-secondary-dark/15 border border-white/5 hover:border-accent-green/20 hover:bg-secondary-dark/40 rounded-2xl overflow-hidden cursor-pointer transition-all duration-300 shadow-[0_15px_35px_rgba(0,0,0,0.5)]"
    >
                    <div>
                      {/* Image Socket */}
                     <div className="relative aspect-[4/5] overflow-hidden bg-black/40 border-b border-white/5">
  {/* Gradient overlay */}
  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/10 to-transparent opacity-60 z-10" />

  {isVideo ? (
  <video
    src={post.thumbnail}
    muted
    loop
    playsInline
    autoPlay
    className="w-full h-full object-cover"
  />
) : (
  <img
    src={post.thumbnail}
    alt={post.title}
    className="w-full h-full object-cover"
  />
)}

  {/* Badges Overlay */}
  <div className="absolute top-4 left-4 z-20 flex gap-2">
    <span className="bg-black/80 text-accent-green border border-accent-green/20 font-extrabold text-[8px] uppercase tracking-widest px-2.5 py-1 rounded-md">
      {post.category}
    </span>
  </div>
</div>

                      {/* Content Card Body */}
                      <div className="p-6 pb-2">
                        
                        {/* Meta: Date & Reading badge */}
                        <div className="flex items-center gap-3 text-[9px] font-sans font-bold uppercase tracking-widest text-muted-text mb-4">
                          <span className="flex items-center gap-1">
                            <Calendar size={10} className="text-accent-green/80" />
                            {post.date}
                          </span>
                          <span>•</span>
                          <span className="flex items-center gap-1">
                            <Clock size={10} className="text-white/35" />
                            {post.readingTime}
                          </span>
                        </div>

                        {/* Title */}
                        <h3 className="text-lg font-sans font-extrabold text-white group-hover:text-accent-green transition-colors duration-300 leading-snug uppercase tracking-wide mb-3">
                          {post.title}
                        </h3>

                        {/* Excerpt */}
                      <ExpandableExcerpt text={post.excerpt} />

                      </div>
                    </div>

                    {/* Card Footer: Author Profile & Detail Arrow */}
                    <div className="p-6 pt-4 mt-6 border-t border-white/5 flex items-center justify-between">
                      
                      <div className="flex items-center gap-3">
                        <img
                          src={post.author.avatar}
                          alt={post.author.name}
                          className="h-8 w-8 rounded-full border border-white/10 object-cover"
                        />
                        <div className="flex flex-col">
                          <span className="text-[10px] font-bold text-white uppercase tracking-wider">
                            {post.author.name}
                          </span>
                          <span className="text-[8px] text-muted-text uppercase tracking-widest mt-0.5">
                            {post.author.role}
                          </span>
                        </div>
                      </div>

                      {/* Floating Circle Arrow */}
                      <div className="w-8 h-8 rounded-full bg-white/[0.02] border border-white/10 group-hover:bg-accent-green group-hover:border-accent-green group-hover:text-black flex items-center justify-center text-white/50 transition-all duration-300 shrink-0">
                        <ArrowUpRight size={14} className="group-hover:rotate-45 transition-transform duration-300" />
                      </div>

                    </div>

                  </motion.article>
  );

})}
              </motion.div>
            ) : (
              // Empty State UI
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="flex flex-col items-center justify-center py-20 px-6 rounded-2xl bg-secondary-dark/10 border border-white/5 max-w-lg mx-auto text-center"
              >
                <div className="h-14 w-14 rounded-full bg-white/[0.01] border border-white/10 flex items-center justify-center text-white/20 mb-6">
                  <FolderOpen size={24} />
                </div>
                <h3 className="text-lg font-heading text-white uppercase tracking-widest mb-2">No Stories Discovered</h3>
                <p className="text-xs text-muted-text font-sans leading-relaxed max-w-sm mb-8">
                  We couldn't find any articles matching "{searchQuery}" under the category "{selectedCategory}". Try updating your query or category filters.
                </p>
                <button
                  onClick={resetFilters}
                  className="flex items-center gap-2 px-5 py-2.5 rounded-full bg-white/5 border border-white/10 hover:border-accent-green text-xs font-bold text-white uppercase tracking-widest hover:text-black hover:bg-accent-green hover:shadow-[0_0_15px_rgba(0,217,95,0.2)] transition-all duration-300"
                >
                  <RefreshCw size={12} />
                  Reset Ecosystem Filter
                </button>
              </motion.div>
            )}
          </AnimatePresence>
        </motion.div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="flex flex-col sm:flex-row items-center justify-between gap-6 mt-16 pt-10 border-t border-white/5 relative z-10">
            <button
              onClick={() => handlePageChange(currentPage - 1)}
              disabled={currentPage === 1}
              className={`flex items-center gap-2 px-6 py-3 rounded-full border text-xs font-bold uppercase tracking-widest transition-all duration-300 ${
                currentPage === 1
                  ? "border-white/5 text-white/20 cursor-not-allowed"
                  : "border-white/10 text-white/60 hover:text-accent-green hover:border-accent-green hover:bg-accent-green/5 active:scale-95"
              }`}
            >
              ← Previous
            </button>

            <div className="flex flex-wrap items-center justify-center gap-2">
              {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => {
                const isActive = currentPage === page;
                return (
                  <button
                    key={page}
                    onClick={() => handlePageChange(page)}
                    className={`w-10 h-10 rounded-full flex items-center justify-center text-xs font-bold transition-all duration-300 ${
                      isActive
                        ? "bg-accent-green text-background shadow-[0_0_15px_rgba(0,217,95,0.3)]"
                        : "text-white/60 hover:text-white hover:bg-white/5 border border-transparent hover:border-white/10"
                    }`}
                  >
                    {page}
                  </button>
                );
              })}
            </div>

            <button
              onClick={() => handlePageChange(currentPage + 1)}
              disabled={currentPage === totalPages}
              className={`flex items-center gap-2 px-6 py-3 rounded-full border text-xs font-bold uppercase tracking-widest transition-all duration-300 ${
                currentPage === totalPages
                  ? "border-white/5 text-white/20 cursor-not-allowed"
                  : "border-white/10 text-white/60 hover:text-accent-green hover:border-accent-green hover:bg-accent-green/5 active:scale-95"
              }`}
            >
              Next →
            </button>
          </div>
        )}

      </div>
    </section>
  );
}
